let file = """{"version":3,"file":"KeybindingPanel-BUIPVbDO.js","names":["$t","$t","$t","$t","$t","$t","$t","$t"],"sources":["../../src/components/dialog/content/setting/keybinding/EditKeybindingContent.vue","../../src/components/dialog/content/setting/keybinding/EditKeybindingContent.vue","../../src/components/dialog/content/setting/keybinding/EditKeybindingFooter.vue","../../src/components/dialog/content/setting/keybinding/EditKeybindingFooter.vue","../../src/components/dialog/content/setting/keybinding/EditKeybindingHeader.vue","../../src/composables/useEditKeybindingDialog.ts","../../src/components/dialog/content/setting/keybinding/UnsavedChangesContent.vue","../../src/components/dialog/content/setting/keybinding/UnsavedChangesContent.vue","../../src/components/dialog/content/setting/keybinding/UnsavedChangesHeader.vue","../../src/components/dialog/content/setting/keybinding/UnsavedChangesHeader.vue","../../src/platform/keybindings/types.ts","../../src/platform/keybindings/presetService.ts","../../src/components/dialog/content/setting/keybinding/KeyComboDisplay.vue","../../src/components/dialog/content/setting/keybinding/KeyComboDisplay.vue","../../src/components/dialog/content/setting/keybinding/KeybindingList.vue","../../src/components/dialog/content/setting/keybinding/KeybindingList.vue","../../src/components/dialog/content/setting/keybinding/KeybindingCommandRows.vue","../../src/components/dialog/content/setting/keybinding/KeybindingCommandRows.vue","../../src/components/dialog/content/setting/keybinding/KeybindingPresetToolbar.vue","../../src/components/dialog/content/setting/keybinding/KeybindingPresetToolbar.vue","../../src/components/dialog/content/setting/KeybindingPanel.vue","../../src/components/dialog/content/setting/KeybindingPanel.vue"],"sourcesContent":["<template>\n  <div class=\"flex w-96 flex-col border-t border-border-default px-4\">\n    <p class=\"mb-4 text-sm text-muted-foreground\">\n      {{ $t('g.setAKeybindingForTheFollowing') }}\n    </p>\n    <div class=\"mb-4 text-sm text-base-foreground\">\n      {{ commandLabel }}\n    </div>\n\n    <input\n      class=\"mb-4 w-full rounded-sm border border-border-default bg-secondary-background px-3 py-2 text-center text-base-foreground shadow-none focus:outline-none\"\n      :value=\"dialogState.newCombo?.toString() ?? ''\"\n      :placeholder=\"$t('g.enterYourKeybind')\"\n      :aria-label=\"$t('g.enterYourKeybind')\"\n      autocomplete=\"off\"\n      autofocus\n      @keydown.stop.prevent=\"captureKeybinding\"\n    />\n    <div class=\"min-h-12\">\n      <p\n        v-if=\"dialogState.newCombo?.isBrowserReserved\"\n        class=\"m-0 text-sm text-destructive-background\"\n      >\n        {{ $t('g.browserReservedKeybinding') }}\n      </p>\n      <p\n        v-else-if=\"existingKeybindingOnCombo\"\n        class=\"m-0 text-sm text-destructive-background\"\n      >\n        {{ $t('g.keybindingAlreadyExists') }}\n        {{ existingKeybindingOnCombo.commandId }}\n      </p>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport type { KeybindingImpl } from '@/platform/keybindings/keybinding'\nimport { KeyComboImpl } from '@/platform/keybindings/keyCombo'\n\nimport type { EditKeybindingDialogState } from '@/composables/useEditKeybindingDialog'\n\nconst { dialogState, onUpdateCombo, existingKeybindingOnCombo } = defineProps<{\n  dialogState: EditKeybindingDialogState\n  commandLabel: string\n  onUpdateCombo: (combo: KeyComboImpl) => void\n  existingKeybindingOnCombo: KeybindingImpl | null\n}>()\n\nfunction captureKeybinding(event: KeyboardEvent) {\n  if (!event.shiftKey && !event.altKey && !event.ctrlKey && !event.metaKey) {\n    if (event.key === 'Escape') return\n  }\n  onUpdateCombo(KeyComboImpl.fromEvent(event))\n}\n</script>\n","<template>\n  <div class=\"flex w-96 flex-col border-t border-border-default px-4\">\n    <p class=\"mb-4 text-sm text-muted-foreground\">\n      {{ $t('g.setAKeybindingForTheFollowing') }}\n    </p>\n    <div class=\"mb-4 text-sm text-base-foreground\">\n      {{ commandLabel }}\n    </div>\n\n    <input\n      class=\"mb-4 w-full rounded-sm border border-border-default bg-secondary-background px-3 py-2 text-center text-base-foreground shadow-none focus:outline-none\"\n      :value=\"dialogState.newCombo?.toString() ?? ''\"\n      :placeholder=\"$t('g.enterYourKeybind')\"\n      :aria-label=\"$t('g.enterYourKeybind')\"\n      autocomplete=\"off\"\n      autofocus\n      @keydown.stop.prevent=\"captureKeybinding\"\n    />\n    <div class=\"min-h-12\">\n      <p\n        v-if=\"dialogState.newCombo?.isBrowserReserved\"\n        class=\"m-0 text-sm text-destructive-background\"\n      >\n        {{ $t('g.browserReservedKeybinding') }}\n      </p>\n      <p\n        v-else-if=\"existingKeybindingOnCombo\"\n        class=\"m-0 text-sm text-destructive-background\"\n      >\n        {{ $t('g.keybindingAlreadyExists') }}\n        {{ existingKeybindingOnCombo.commandId }}\n      </p>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport type { KeybindingImpl } from '@/platform/keybindings/keybinding'\nimport { KeyComboImpl } from '@/platform/keybindings/keyCombo'\n\nimport type { EditKeybindingDialogState } from '@/composables/useEditKeybindingDialog'\n\nconst { dialogState, onUpdateCombo, existingKeybindingOnCombo } = defineProps<{\n  dialogState: EditKeybindingDialogState\n  commandLabel: string\n  onUpdateCombo: (combo: KeyComboImpl) => void\n  existingKeybindingOnCombo: KeybindingImpl | null\n}>()\n\nfunction captureKeybinding(event: KeyboardEvent) {\n  if (!event.shiftKey && !event.altKey && !event.ctrlKey && !event.metaKey) {\n    if (event.key === 'Escape') return\n  }\n  onUpdateCombo(KeyComboImpl.fromEvent(event))\n}\n</script>\n","<template>\n  <div class=\"flex w-full justify-end gap-2 px-4 py-2\">\n    <Button\n      variant=\"textonly\"\n      size=\"md\"\n      class=\"text-muted-foreground\"\n      @click=\"handleCancel\"\n    >\n      {{ $t('g.cancel') }}\n    </Button>\n    <Button\n      :variant=\"\n        existingKeybindingOnCombo\n          ? 'destructive'\n          : dialogState.newCombo?.isBrowserReserved\n            ? 'secondary'\n            : 'primary'\n      \"\n      size=\"md\"\n      :disabled=\"!dialogState.newCombo\"\n      class=\"px-4 py-2\"\n      @click=\"handleSave\"\n    >\n      {{\n        existingKeybindingOnCombo\n          ? $t('g.overwrite')\n          : dialogState.newCombo?.isBrowserReserved\n            ? $t('g.saveAnyway')\n            : $t('g.save')\n      }}\n    </Button>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport type { Reactive } from 'vue'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { KeybindingImpl } from '@/platform/keybindings/keybinding'\nimport { useKeybindingService } from '@/platform/keybindings/keybindingService'\nimport { useKeybindingStore } from '@/platform/keybindings/keybindingStore'\nimport { useDialogStore } from '@/stores/dialogStore'\n\nimport type { EditKeybindingDialogState } from '@/composables/useEditKeybindingDialog'\nimport { DIALOG_KEY } from '@/composables/useEditKeybindingDialog'\n\nconst { dialogState, existingKeybindingOnCombo } = defineProps<{\n  dialogState: Reactive<EditKeybindingDialogState>\n  existingKeybindingOnCombo: KeybindingImpl | null\n}>()\n\nconst keybindingStore = useKeybindingStore()\nconst keybindingService = useKeybindingService()\nconst dialogStore = useDialogStore()\n\nfunction handleCancel() {\n  dialogStore.closeDialog({ key: DIALOG_KEY })\n}\n\nasync function handleSave() {\n  const combo = dialogState.newCombo\n  const commandId = dialogState.commandId\n  if (!combo || !commandId) return\n\n  dialogStore.closeDialog({ key: DIALOG_KEY })\n\n  if (dialogState.mode === 'add') {\n    keybindingStore.addUserKeybinding(new KeybindingImpl({ commandId, combo }))\n  } else if (dialogState.existingBinding) {\n    keybindingStore.updateSpecificKeybinding(\n      dialogState.existingBinding,\n      new KeybindingImpl({ commandId, combo })\n    )\n  } else {\n    keybindingStore.updateKeybindingOnCommand(\n      new KeybindingImpl({ commandId, combo })\n    )\n  }\n  await keybindingService.persistUserKeybindings()\n}\n</script>\n","<template>\n  <div class=\"flex w-full justify-end gap-2 px-4 py-2\">\n    <Button\n      variant=\"textonly\"\n      size=\"md\"\n      class=\"text-muted-foreground\"\n      @click=\"handleCancel\"\n    >\n      {{ $t('g.cancel') }}\n    </Button>\n    <Button\n      :variant=\"\n        existingKeybindingOnCombo\n          ? 'destructive'\n          : dialogState.newCombo?.isBrowserReserved\n            ? 'secondary'\n            : 'primary'\n      \"\n      size=\"md\"\n      :disabled=\"!dialogState.newCombo\"\n      class=\"px-4 py-2\"\n      @click=\"handleSave\"\n    >\n      {{\n        existingKeybindingOnCombo\n          ? $t('g.overwrite')\n          : dialogState.newCombo?.isBrowserReserved\n            ? $t('g.saveAnyway')\n            : $t('g.save')\n      }}\n    </Button>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport type { Reactive } from 'vue'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { KeybindingImpl } from '@/platform/keybindings/keybinding'\nimport { useKeybindingService } from '@/platform/keybindings/keybindingService'\nimport { useKeybindingStore } from '@/platform/keybindings/keybindingStore'\nimport { useDialogStore } from '@/stores/dialogStore'\n\nimport type { EditKeybindingDialogState } from '@/composables/useEditKeybindingDialog'\nimport { DIALOG_KEY } from '@/composables/useEditKeybindingDialog'\n\nconst { dialogState, existingKeybindingOnCombo } = defineProps<{\n  dialogState: Reactive<EditKeybindingDialogState>\n  existingKeybindingOnCombo: KeybindingImpl | null\n}>()\n\nconst keybindingStore = useKeybindingStore()\nconst keybindingService = useKeybindingService()\nconst dialogStore = useDialogStore()\n\nfunction handleCancel() {\n  dialogStore.closeDialog({ key: DIALOG_KEY })\n}\n\nasync function handleSave() {\n  const combo = dialogState.newCombo\n  const commandId = dialogState.commandId\n  if (!combo || !commandId) return\n\n  dialogStore.closeDialog({ key: DIALOG_KEY })\n\n  if (dialogState.mode === 'add') {\n    keybindingStore.addUserKeybinding(new KeybindingImpl({ commandId, combo }))\n  } else if (dialogState.existingBinding) {\n    keybindingStore.updateSpecificKeybinding(\n      dialogState.existingBinding,\n      new KeybindingImpl({ commandId, combo })\n    )\n  } else {\n    keybindingStore.updateKeybindingOnCommand(\n      new KeybindingImpl({ commandId, combo })\n    )\n  }\n  await keybindingService.persistUserKeybindings()\n}\n</script>\n","<template>\n  <div class=\"flex w-full items-center gap-2 p-4\">\n    <p class=\"m-0 font-semibold\">{{ $t('g.modifyKeybinding') }}</p>\n  </div>\n</template>\n","import { computed, reactive } from 'vue'\n\nimport EditKeybindingContent from '@/components/dialog/content/setting/keybinding/EditKeybindingContent.vue'\nimport EditKeybindingFooter from '@/components/dialog/content/setting/keybinding/EditKeybindingFooter.vue'\nimport EditKeybindingHeader from '@/components/dialog/content/setting/keybinding/EditKeybindingHeader.vue'\nimport type { KeyComboImpl } from '@/platform/keybindings/keyCombo'\nimport type { KeybindingImpl } from '@/platform/keybindings/keybinding'\nimport { useKeybindingStore } from '@/platform/keybindings/keybindingStore'\nimport { useDialogService } from '@/services/dialogService'\n\nexport const DIALOG_KEY = 'edit-keybinding'\n\nexport interface EditKeybindingDialogState {\n  commandId: string\n  newCombo: KeyComboImpl | null\n  currentCombo: KeyComboImpl | null\n  mode: 'edit' | 'add'\n  existingBinding: KeybindingImpl | null\n}\n\nexport function useEditKeybindingDialog() {\n  const { showSmallLayoutDialog } = useDialogService()\n  const keybindingStore = useKeybindingStore()\n\n  function show(options: {\n    commandId: string\n    commandLabel: string\n    currentCombo: KeyComboImpl | null\n    mode?: 'edit' | 'add'\n    existingBinding?: KeybindingImpl | null\n  }) {\n    const dialogState = reactive<EditKeybindingDialogState>({\n      commandId: options.commandId,\n      newCombo: options.currentCombo,\n      currentCombo: options.currentCombo,\n      mode: options.mode ?? 'edit',\n      existingBinding: options.existingBinding ?? null\n    })\n\n    const existingKeybindingOnCombo = computed(() => {\n      if (!dialogState.newCombo) return null\n      if (dialogState.currentCombo?.equals(dialogState.newCombo)) return null\n      return keybindingStore.getKeybinding(dialogState.newCombo)\n    })\n\n    function onUpdateCombo(combo: KeyComboImpl) {\n      dialogState.newCombo = combo\n    }\n\n    showSmallLayoutDialog({\n      key: DIALOG_KEY,\n      headerComponent: EditKeybindingHeader,\n      footerComponent: EditKeybindingFooter,\n      component: EditKeybindingContent,\n      props: {\n        dialogState,\n        onUpdateCombo,\n        commandLabel: options.commandLabel,\n        existingKeybindingOnCombo\n      },\n      headerProps: {},\n      footerProps: { dialogState, existingKeybindingOnCombo }\n    })\n  }\n\n  return { show }\n}\n","<template>\n  <div\n    class=\"flex w-full max-w-[420px] flex-col border-t border-border-default\"\n  >\n    <div class=\"flex flex-col gap-4 p-4\">\n      <p class=\"m-0 text-sm text-muted-foreground\">\n        {{ $t('g.keybindingPresets.unsavedChangesMessage') }}\n      </p>\n      <div class=\"flex justify-end gap-2\">\n        <Button\n          variant=\"textonly\"\n          class=\"text-muted-foreground\"\n          @click=\"onResult(null)\"\n        >\n          {{ $t('g.cancel') }}\n        </Button>\n        <Button\n          variant=\"secondary\"\n          class=\"bg-secondary-background\"\n          @click=\"onResult(false)\"\n        >\n          {{ $t('g.keybindingPresets.discardAndSwitch') }}\n        </Button>\n        <Button\n          variant=\"secondary\"\n          class=\"bg-base-foreground text-base-background\"\n          @click=\"onResult(true)\"\n        >\n          {{ $t('g.keybindingPresets.saveAndSwitch') }}\n        </Button>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport Button from '@/components/ui/button/Button.vue'\n\nconst { onResult } = defineProps<{\n  onResult: (result: boolean | null) => void\n}>()\n</script>\n","<template>\n  <div\n    class=\"flex w-full max-w-[420px] flex-col border-t border-border-default\"\n  >\n    <div class=\"flex flex-col gap-4 p-4\">\n      <p class=\"m-0 text-sm text-muted-foreground\">\n        {{ $t('g.keybindingPresets.unsavedChangesMessage') }}\n      </p>\n      <div class=\"flex justify-end gap-2\">\n        <Button\n          variant=\"textonly\"\n          class=\"text-muted-foreground\"\n          @click=\"onResult(null)\"\n        >\n          {{ $t('g.cancel') }}\n        </Button>\n        <Button\n          variant=\"secondary\"\n          class=\"bg-secondary-background\"\n          @click=\"onResult(false)\"\n        >\n          {{ $t('g.keybindingPresets.discardAndSwitch') }}\n        </Button>\n        <Button\n          variant=\"secondary\"\n          class=\"bg-base-foreground text-base-background\"\n          @click=\"onResult(true)\"\n        >\n          {{ $t('g.keybindingPresets.saveAndSwitch') }}\n        </Button>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport Button from '@/components/ui/button/Button.vue'\n\nconst { onResult } = defineProps<{\n  onResult: (result: boolean | null) => void\n}>()\n</script>\n","<template>\n  <div class=\"flex w-full items-center p-4\">\n    <p class=\"m-0 text-sm font-medium\">\n      {{ $t('g.keybindingPresets.unsavedChangesTo', { name: presetName }) }}\n    </p>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nconst { presetName } = defineProps<{\n  presetName: string\n}>()\n</script>\n","<template>\n  <div class=\"flex w-full items-center p-4\">\n    <p class=\"m-0 text-sm font-medium\">\n      {{ $t('g.keybindingPresets.unsavedChangesTo', { name: presetName }) }}\n    </p>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nconst { presetName } = defineProps<{\n  presetName: string\n}>()\n</script>\n","import { z } from 'zod'\n\nconst zKeyCombo = z.object({\n  key: z.string(),\n  ctrl: z.boolean().optional(),\n  alt: z.boolean().optional(),\n  shift: z.boolean().optional(),\n  meta: z.boolean().optional()\n})\n\nconst zKeybinding = z.object({\n  commandId: z.string(),\n  combo: zKeyCombo,\n  targetElementId: z.string().optional()\n})\n\nexport const zKeybindingPreset = z.object({\n  name: z.string().trim().min(1, 'Preset name cannot be empty'),\n  newBindings: z.array(zKeybinding),\n  unsetBindings: z.array(zKeybinding)\n})\n\nexport type KeyCombo = z.infer<typeof zKeyCombo>\nexport type Keybinding = z.infer<typeof zKeybinding>\nexport type KeybindingPreset = z.infer<typeof zKeybindingPreset>\n","import { toRaw } from 'vue'\nimport { fromZodError } from 'zod-validation-error'\n\nimport { downloadBlob } from '@/base/common/downloadUtil'\nimport UnsavedChangesContent from '@/components/dialog/content/setting/keybinding/UnsavedChangesContent.vue'\nimport UnsavedChangesHeader from '@/components/dialog/content/setting/keybinding/UnsavedChangesHeader.vue'\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport { t } from '@/i18n'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { api } from '@/scripts/api'\nimport { uploadFile } from '@/scripts/utils'\nimport { useDialogService } from '@/services/dialogService'\nimport { useDialogStore } from '@/stores/dialogStore'\n\nimport { KeybindingImpl } from './keybinding'\nimport { useKeybindingService } from './keybindingService'\nimport { useKeybindingStore } from './keybindingStore'\nimport type { KeybindingPreset } from './types'\nimport { zKeybindingPreset } from './types'\n\nconst PRESETS_DIR = 'keybindings'\n\nfunction presetFilePath(name: string): string {\n  const trimmed = name.trim()\n  if (\n    !trimmed ||\n    trimmed === 'default' ||\n    trimmed.toLowerCase().endsWith('.json') ||\n    trimmed.includes('/') ||\n    trimmed.includes('\\\\') ||\n    trimmed.includes('..') ||\n    trimmed.startsWith('.')\n  ) {\n    throw new Error(t('g.keybindingPresets.invalidPresetName'))\n  }\n  return `${PRESETS_DIR}/${trimmed}.json`\n}\n\nfunction buildPresetFromStore(\n  name: string,\n  keybindingStore: ReturnType<typeof useKeybindingStore>\n): KeybindingPreset {\n  const newBindings = toRaw(keybindingStore.getUserKeybindingValues())\n  const unsetBindings = toRaw(keybindingStore.getUserUnsetKeybindingValues())\n  return { name, newBindings, unsetBindings }\n}\n\nexport function useKeybindingPresetService() {\n  const keybindingStore = useKeybindingStore()\n  const keybindingService = useKeybindingService()\n  const settingStore = useSettingStore()\n  const dialogService = useDialogService()\n  const dialogStore = useDialogStore()\n  const toast = useToast()\n  const { wrapWithErrorHandlingAsync } = useErrorHandling()\n\n  async function switchToDefaultPreset({ resetBindings = true } = {}) {\n    if (resetBindings) keybindingStore.resetAllKeybindings()\n    keybindingStore.currentPresetName = 'default'\n    keybindingStore.savedPresetData = null\n    await keybindingService.persistUserKeybindings()\n    await settingStore.set('Comfy.Keybinding.CurrentPreset', 'default')\n  }\n\n  const UNSAVED_DIALOG_KEY = 'unsaved-keybinding-changes'\n\n  function showUnsavedChangesDialog(\n    presetName: string\n  ): Promise<boolean | null> {\n    return new Promise((resolve) => {\n      dialogService.showSmallLayoutDialog({\n        key: UNSAVED_DIALOG_KEY,\n        headerComponent: UnsavedChangesHeader,\n        headerProps: { presetName },\n        component: UnsavedChangesContent,\n        props: {\n          onResult: (result: boolean | null) => {\n            resolve(result)\n            dialogStore.closeDialog({ key: UNSAVED_DIALOG_KEY })\n          }\n        },\n        dialogComponentProps: {\n          onClose: () => resolve(null)\n        }\n      })\n    })\n  }\n\n  async function listPresets(): Promise<string[]> {\n    const files = await api.listUserDataFullInfo(PRESETS_DIR)\n    return files\n      .map((f) => f.path.replace(/\\.json$/, ''))\n      .filter((name) => name.length > 0)\n  }\n\n  async function loadPreset(name: string): Promise<KeybindingPreset> {\n    const resp = await api.getUserData(presetFilePath(name))\n    if (!resp.ok) {\n      throw new Error(t('g.keybindingPresets.loadPresetFailed', { name }))\n    }\n    const data = await resp.json()\n    const result = zKeybindingPreset.safeParse(data)\n    if (!result.success) {\n      throw new Error(\n        t('g.keybindingPresets.invalidPresetFile') +\n          ': ' +\n          fromZodError(result.error).message\n      )\n    }\n    return { ...result.data, name }\n  }\n\n  function applyPreset(preset: KeybindingPreset) {\n    keybindingStore.resetAllKeybindings()\n    for (const binding of preset.unsetBindings) {\n      keybindingStore.unsetKeybinding(new KeybindingImpl(binding))\n    }\n    for (const binding of preset.newBindings) {\n      keybindingStore.addUserKeybinding(new KeybindingImpl(binding))\n    }\n    // Snapshot savedPresetData from the store's actual state after applying,\n    // because addUserKeybinding may auto-unset conflicting defaults beyond\n    // what the raw preset specifies.\n    keybindingStore.savedPresetData = buildPresetFromStore(\n      preset.name,\n      keybindingStore\n    )\n    keybindingStore.currentPresetName = preset.name\n  }\n\n  async function savePreset(name: string) {\n    const preset = buildPresetFromStore(name, keybindingStore)\n    await api.storeUserData(presetFilePath(name), JSON.stringify(preset), {\n      overwrite: true,\n      stringify: false\n    })\n    keybindingStore.savedPresetData = preset\n    keybindingStore.currentPresetName = name\n    await keybindingService.persistUserKeybindings()\n    await settingStore.set('Comfy.Keybinding.CurrentPreset', name)\n    toast.success(t('g.keybindingPresets.presetSaved', { name }), {\n      duration: 3000\n    })\n  }\n\n  async function deletePreset(name: string) {\n    const confirmed = await dialogService.confirm({\n      title: t('g.keybindingPresets.deletePresetTitle'),\n      message: t('g.keybindingPresets.deletePresetWarning'),\n      type: 'delete'\n    })\n    if (!confirmed) return\n\n    const resp = await api.deleteUserData(presetFilePath(name))\n    if (!resp.ok) {\n      throw new Error(t('g.keybindingPresets.deletePresetFailed', { name }))\n    }\n\n    if (keybindingStore.currentPresetName === name) {\n      await switchToDefaultPreset()\n    }\n\n    toast.info(t('g.keybindingPresets.presetDeleted', { name }), {\n      duration: 3000\n    })\n  }\n\n  function exportPreset() {\n    const preset = buildPresetFromStore(\n      keybindingStore.currentPresetName,\n      keybindingStore\n    )\n    downloadBlob(\n      `${preset.name}.json`,\n      new Blob([JSON.stringify(preset, null, 2)], {\n        type: 'application/json'\n      })\n    )\n  }\n\n  async function importPreset() {\n    const file = await uploadFile('application/json')\n    const text = await file.text()\n    let data: unknown\n    try {\n      data = JSON.parse(text)\n    } catch {\n      throw new Error(t('g.keybindingPresets.invalidPresetFile'))\n    }\n    const result = zKeybindingPreset.safeParse(data)\n    if (!result.success) {\n      throw new Error(\n        t('g.keybindingPresets.invalidPresetFile') +\n          ': ' +\n          fromZodError(result.error).message\n      )\n    }\n    const preset = result.data\n\n    // Save the imported preset file to storage\n    await api.storeUserData(\n      presetFilePath(preset.name),\n      JSON.stringify(preset),\n      { overwrite: true, stringify: false }\n    )\n\n    // Switch to the imported preset (handles dirty check)\n    await switchPreset(preset.name)\n\n    toast.success(t('g.keybindingPresets.presetImported'), { duration: 3000 })\n  }\n\n  async function promptAndSaveNewPreset(): Promise<boolean> {\n    const name = await dialogService.prompt({\n      title: t('g.keybindingPresets.saveAsNewPreset'),\n      message: t('g.keybindingPresets.presetNamePrompt'),\n      defaultValue: ''\n    })\n    if (!name) return false\n    const trimmedName = name.trim()\n    if (!trimmedName) return false\n    const existingPresets = await listPresets()\n    if (existingPresets.includes(trimmedName)) {\n      const overwrite = await dialogService.confirm({\n        title: t('g.keybindingPresets.overwritePresetTitle'),\n        message: t('g.keybindingPresets.overwritePresetMessage', {\n          name: trimmedName\n        }),\n        type: 'overwrite'\n      })\n      if (!overwrite) return false\n    }\n    await savePreset(trimmedName)\n    return true\n  }\n\n  async function switchPreset(targetName: string) {\n    if (keybindingStore.isCurrentPresetModified) {\n      const displayName =\n        keybindingStore.currentPresetName === 'default'\n          ? t('g.keybindingPresets.default')\n          : keybindingStore.currentPresetName\n      const result = await showUnsavedChangesDialog(displayName)\n\n      if (result === null) return\n      if (result) {\n        if (keybindingStore.currentPresetName !== 'default') {\n          await savePreset(keybindingStore.currentPresetName)\n        } else {\n          const saved = await promptAndSaveNewPreset()\n          if (!saved) return\n        }\n      }\n    }\n\n    if (targetName === 'default') {\n      await switchToDefaultPreset()\n      return\n    }\n\n    const preset = await loadPreset(targetName)\n    applyPreset(preset)\n    await keybindingService.persistUserKeybindings()\n    await settingStore.set('Comfy.Keybinding.CurrentPreset', targetName)\n  }\n\n  return {\n    listPresets: wrapWithErrorHandlingAsync(listPresets),\n    loadPreset: wrapWithErrorHandlingAsync(loadPreset),\n    savePreset: wrapWithErrorHandlingAsync(savePreset),\n    deletePreset: wrapWithErrorHandlingAsync(deletePreset),\n    exportPreset,\n    importPreset: wrapWithErrorHandlingAsync(importPreset),\n    switchPreset: wrapWithErrorHandlingAsync(switchPreset),\n    switchToDefaultPreset: wrapWithErrorHandlingAsync(switchToDefaultPreset),\n    promptAndSaveNewPreset: wrapWithErrorHandlingAsync(promptAndSaveNewPreset),\n    applyPreset\n  }\n}\n","<template>\n  <span class=\"flex flex-row gap-0.5\">\n    <template v-for=\"(sequence, index) in keySequences\" :key=\"index\">\n      <Badge\n        class=\"min-w-6 justify-center gap-1 bg-interface-menu-keybind-surface-default text-center font-normal text-base-foreground capitalize\"\n        :severity=\"isModified ? 'info' : 'secondary'\"\n      >\n        {{ sequence }}\n      </Badge>\n    </template>\n  </span>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport Badge from '@/components/ui/badge/Badge.vue'\nimport type { KeyComboImpl } from '@/platform/keybindings/keyCombo'\n\nconst { keyCombo, isModified = false } = defineProps<{\n  keyCombo: KeyComboImpl\n  isModified?: boolean\n}>()\n\nconst keySequences = computed(() => keyCombo.getKeySequences())\n</script>\n","<template>\n  <span class=\"flex flex-row gap-0.5\">\n    <template v-for=\"(sequence, index) in keySequences\" :key=\"index\">\n      <Badge\n        class=\"min-w-6 justify-center gap-1 bg-interface-menu-keybind-surface-default text-center font-normal text-base-foreground capitalize\"\n        :severity=\"isModified ? 'info' : 'secondary'\"\n      >\n        {{ sequence }}\n      </Badge>\n    </template>\n  </span>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport Badge from '@/components/ui/